"""Provenance shared by entry-scoped analysis fit files."""

import re
from datetime import datetime

from pydantic import BaseModel, ConfigDict, field_validator


class AnalysisSource(BaseModel):
    """Evidence for an analysis result, never generated by storage.

    run_id is a nonempty opaque historical run identifier or null when unknown.
    created_at is the original YYYY-MM-DDTHH:MM[:SS[.ffffff]] timestamp with
    Z or +/-HH:MM timezone, or null when unproven. Fractional seconds have one
    to six digits. Both keys are required. Strings retain their exact spelling.
    Extra fields, blank strings and other timestamp forms are rejected.
    """

    model_config = ConfigDict(strict=True, extra="forbid")
    run_id: str | None
    created_at: str | None

    @field_validator("run_id", "created_at")
    @classmethod
    def nonempty(cls, value: str | None) -> str | None:
        """Reject blank evidence strings; preserve nonblank strings verbatim."""
        if value is not None and not value.strip():
            raise ValueError("source values must be nonempty strings or null")
        return value

    @field_validator("created_at")
    @classmethod
    def timezone_required(cls, value: str | None) -> str | None:
        """Require the documented calendar timestamp form; preserve its text."""
        if value is not None:
            if (
                re.fullmatch(
                    r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}"
                    r"(?::[0-9]{2}(?:\.[0-9]{1,6})?)?(?:Z|[+-][0-9]{2}:[0-5][0-9])",
                    value,
                )
                is None
            ):
                raise ValueError("created_at requires timezone-aware extended ISO 8601")
            parsed = datetime.fromisoformat(value)
            if parsed.utcoffset() is None:
                raise ValueError("created_at requires timezone-aware ISO 8601")
        return value
